SELECT GROUP_CONCAT(v) FROM t;

SELECT group_concat(v, w) FROM t;

SELECT GROUP_CONCAT(DISTINCT v, w ORDER BY w DESC, v SEPARATOR '|') FROM t;

SELECT GROUP_CONCAT(v ORDER BY 1) FROM t;

SELECT GROUP_CONCAT(v SEPARATOR "|"), GROUP_CONCAT(v SEPARATOR '') FROM t;

SELECT GROUP_CONCAT(v SEPARATOR X'7C'), GROUP_CONCAT(v SEPARATOR 0x7C) FROM t;

SELECT GROUP_CONCAT(v SEPARATOR b'01111100'), GROUP_CONCAT(v SEPARATOR 0b01111100) FROM t;

-- Both servers' parsers accept OVER here; execution then reports it as unsupported.
SELECT GROUP_CONCAT(v ORDER BY v) OVER (PARTITION BY w) FROM t;
